package com.ethk3.novaonepro.strategyv2;
import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.ethk3.novaonepro.TargetIssueResolver;import java.util.*;

/** Kind-specific computations from original research objects. No chart cache, formal outcome feedback or invented teacher. */
public final class MatrixEvidenceR30R1 {
 private MatrixEvidenceR30R1(){}
 static List<PolicySpecR27> teachers(List<PolicySpecR27> candidates){List<PolicySpecR27> out=new ArrayList<>();for(PolicySpecR27 p:candidates)if(out.stream().noneMatch(x->x.policyHash().equals(p.policyHash()))&&ResearchStudyTaskR30R1.supported(p)&&!SetIntersectionPolicyR30.exact(p)&&(out.isEmpty()||out.get(0).position==p.position)){out.add(p);if(out.size()==4)break;}return out;}
 static MatrixTensorR30R1.Tensor tensor(String kind,EvalContextR27 c,long revision,List<String> rows,List<String> cols,double[][] values,long[][] n,Map<String,Object> details){String through=c.data.issues[c.split.selectTo-1];details.put("role","SELECT");details.put("formalLabelsRead",0);details.put("scope","ORIGINAL_SELECT_CAUSAL_REPLAY_OR_MACHINE_RESEARCH_NOT_SAVED_LIVE_PREDRAW_OR_NATURAL_CERTIFICATE");details.put("abi",FrozenConfirmationR30.currentSemantics());return new MatrixTensorR30R1.Tensor(kind,"SELECT",c.data.datasetHash,StatsR27.sha256("MATRIX_RESEARCH_SOURCE:"+kind),through,TargetIssueResolver.next(through).targetIssue,revision,rows,cols,values,n,details);}
 static List<String> names(List<PolicySpecR27> ps){List<String> out=new ArrayList<>();for(PolicySpecR27 p:ps)out.add(p.policyHash());return out;}
 public static MatrixTensorR30R1.Tensor compute(String kind,EvalContextR27 c,List<PolicySpecR27> candidates,long revision){
  if(c.labels!=c.data.draws)throw new IllegalArgumentException("TYPED_MATRIX_ORIGINAL_SELECT");List<PolicySpecR27> ps=teachers(candidates);Map<String,Object> d=new LinkedHashMap<>();int from=c.split.selectFrom,to=c.split.selectTo;if(from>=to)return null;
  if(kind.equals("EVIDENCE_TEACHER")){
   if(ps.isEmpty())return null;double[][] v=new double[ps.size()][10];long[][] n=new long[ps.size()][10];for(int i=0;i<ps.size();i++){ReplayEvaluatorR27.Trace tr=FusionStudyR30R1.trace(ps.get(i),c);for(int t=from;t<to;t++)if(tr.probabilityRows[t]!=null&&!tr.skipped[t])for(int k=0;k<10;k++){v[i][k]+=tr.probabilityRows[t][k];n[i][k]++;}for(int k=0;k<10;k++)if(n[i][k]>0)v[i][k]/=n[i][k];}d.put("teacherKind","ORIGINAL_ARCHIVE_POLICY_AS_RESEARCH_TEACHER_NOT_F23_VM_SUBSTITUTE");d.put("targetPosition",ps.get(0).position);d.put("teacherPrograms",programs(ps));return tensor(kind,c,revision,names(ps),MatrixResearchR30R1.labels("number",10),v,n,d);
  }
  if(kind.equals("TEACHER_DIVERSITY")||kind.equals("ALGORITHM_COMPLEMENTARITY")){
   if(ps.size()<2)return null;double[][] v=new double[ps.size()][ps.size()];long[][] n=new long[ps.size()][ps.size()];List<Object> pairs=new ArrayList<>();for(int i=0;i<ps.size();i++)for(int j=0;j<=i;j++){FusionStudyR30R1.Pair pair=FusionStudyR30R1.pair(ps.get(i),ps.get(j),c);double value=0;long count=0;if(kind.equals("TEACHER_DIVERSITY")){ReplayEvaluatorR27.Trace a=FusionStudyR30R1.trace(ps.get(i),c),b=FusionStudyR30R1.trace(ps.get(j),c);for(int t=from;t<to;t++){if((t&31)==0)CooperativeContinuationR26.poll();if(a.probabilityRows[t]==null||b.probabilityRows[t]==null)continue;double js=0;for(int k=0;k<10;k++){double x=a.probabilityRows[t][k],y=b.probabilityRows[t][k],mid=(x+y)/2;if(x>0)js+=.5*x*Math.log(x/mid);if(y>0)js+=.5*y*Math.log(y/mid);}value+=js;count++;}if(count>0)value/=count;}else if(pair.eitherMiss>0){value=1-pair.bothMiss/(double)pair.eitherMiss;count=pair.n;}v[i][j]=v[j][i]=value;n[i][j]=n[j][i]=count;Map<String,Object> detail=pair.json();detail.put("a",ps.get(i).policyHash());detail.put("b",ps.get(j).policyHash());pairs.add(detail);}d.put("pairs",pairs);d.put("estimator",kind.equals("TEACHER_DIVERSITY")?"MEAN_PREDRAW_FORECAST_JENSEN_SHANNON_DISTANCE_NO_LABELS":"ONE_MINUS_SAME_TARGET_COMMON_FAILURE_OVER_EITHER_FAILURE");d.put("fusedBenefit",null);d.put("fusedBenefitReason","A new fusion must separately pass actual paired proper-score gain against every parent in FusionOps; matrix screening is not that result");return tensor(kind,c,revision,names(ps),names(ps),v,n,d);
  }
  if(kind.equals("FORWARD_REASONING")||kind.equals("CONTRADICTION")){
   if(ps.isEmpty())return null;double[][] v=new double[ps.size()][3];long[][] n=new long[ps.size()][3];boolean conflict=kind.equals("CONTRADICTION");for(int i=0;i<ps.size();i++){PolicySpecR27 p=ps.get(i);double[] scores=PolicyAstR27.eval(p.ast,c.cache,p.position);ReplayEvaluatorR27.Trace trace=FusionStudyR30R1.trace(p,c);int finite=0,normalized=0,known=0;for(int t=from;t<to;t++){if((t&31)==0)CooperativeContinuationR26.poll();boolean row=true;for(int k=0;k<10;k++)row&=Double.isFinite(scores[t*10+k]);if(row)finite++;if(trace.probabilityRows[t]!=null){known++;if(Double.isFinite(FusionStudyR30R1.loss(trace.probabilityRows[t],1)))normalized++;}}v[i][0]=conflict?(PolicyContractR30.violations(p).isEmpty()?0:1):(PolicyContractR30.violations(p).isEmpty()?1:0);n[i][0]=1;v[i][1]=conflict?(to-from-finite)/(double)(to-from):finite/(double)(to-from);n[i][1]=to-from;v[i][2]=known==0?0:conflict?(known-normalized)/(double)known:normalized/(double)known;n[i][2]=known;}d.put("programsAndPremises",programs(ps));d.put("qualityMeaning","Type/PIT/output premise checks only; no forward outcome advantage asserted");return tensor(kind,c,revision,names(ps),conflict?Arrays.asList("CONTRACT_CONTRADICTION","MISSING_PREMISE_RATE","NONNORMALIZED_OUTPUT_RATE"):Arrays.asList("TYPE_PIT_PREMISE_VALID","AVAILABLE_PREMISE_RATE","NORMALIZED_FORWARD_OUTPUT_RATE"),v,n,d);
  }
  if(kind.equals("REVERSE_REASONING")){
   int target=ps.isEmpty()?1:ps.get(0).position,source=target%10+1;double[][] v=new double[10][10];long[][] n=new long[10][10];long[] totals=new long[10];for(int t=from;t<to;t++)if(c.data.consecutive(t,1)){int previous=c.data.draws[t-1][source-1]-1,actual=c.data.draws[t][target-1]-1;v[actual][previous]++;totals[previous]++;}for(int y=0;y<10;y++)for(int x=0;x<10;x++){v[y][x]=(v[y][x]+1)/(totals[x]+10.0);n[y][x]=totals[x];}d.put("estimator","SMOOTHED_P_TARGET_GIVEN_STRICT_PREVIOUS_SOURCE_NUMBER_HYPOTHESIS_NOT_CAUSAL_IDENTIFICATION");d.put("targetPosition",target);d.put("sourcePosition",source);d.put("lag",1);return tensor(kind,c,revision,MatrixResearchR30R1.labels("targetNumber",10),MatrixResearchR30R1.labels("previousSourceNumber",10),v,n,d);
  }
  if(kind.equals("INVARIANCE")){
   List<PolicySpecR27> eligible=new ArrayList<>();for(PolicySpecR27 p:ps)if(p.ast.kids.length==2&&(p.ast.op.equals("add")||p.ast.op.equals("mul")))eligible.add(p);if(eligible.isEmpty())return null;double[][] v=new double[eligible.size()][3];long[][] n=new long[eligible.size()][3];List<Object> transforms=new ArrayList<>();for(int i=0;i<eligible.size();i++){PolicySpecR27 p=eligible.get(i),swapped=p.withAst(PolicyAstR27.op(p.ast.op,p.ast.kids[1],p.ast.kids[0]),p.meta);double tau=c.temperature(p);ReplayEvaluatorR27.Trace a=ReplayEvaluatorR27.selectTraceWithProbabilities(p,c,tau),b=ReplayEvaluatorR27.selectTraceWithProbabilities(swapped,c,tau);int both=0,match=0,action=0;double worst=0;for(int t=from;t<to;t++)if(a.probabilityRows[t]!=null&&b.probabilityRows[t]!=null){both++;double error=0;for(int k=0;k<10;k++)error=Math.max(error,Math.abs(a.probabilityRows[t][k]-b.probabilityRows[t][k]));worst=Math.max(worst,error);if(error<=1e-12)match++;if(a.act[t]==b.act[t]&&a.signature(t)==b.signature(t))action++;}v[i][0]=both==0?0:match/(double)both;v[i][1]=both==0?0:action/(double)both;v[i][2]=worst;Arrays.fill(n[i],both);Map<String,Object> detail=new LinkedHashMap<>();detail.put("original",p.policyHash());detail.put("transformed",swapped.policyHash());detail.put("transform","PREDECLARED_COMMUTATIVE_BINARY_CHILD_SWAP_ONLY");detail.put("sameFrozenTemperature",tau);transforms.add(detail);}d.put("transforms",transforms);return tensor(kind,c,revision,names(eligible),Arrays.asList("PROBABILITY_MATCH_RATE","DECISION_MATCH_RATE","MAX_PROBABILITY_ABSOLUTE_ERROR"),v,n,d);
  }
  if(kind.equals("ACTION_UTILITY")){
   if(ps.isEmpty())return null;ReplayEvaluatorR27.Trace tr=FusionStudyR30R1.trace(ps.get(0),c);double[][] v=new double[2][3];long[][] n=new long[2][3];for(int t=from;t<to;t++)if(!tr.skipped[t]){int action=tr.act[t]?1:0;v[action][0]+=tr.hit[t];v[action][1]+=1-tr.hit[t];v[action][2]+=action==1?tr.hit[t]-.3:0;for(int k=0;k<3;k++)n[action][k]++;}for(int a=0;a<2;a++)for(int k=0;k<3;k++)if(n[a][k]>0)v[a][k]/=n[a][k];d.put("actionPolicy",ps.get(0).fullJson());d.put("unitUtility","ACT: K3_hit-0.30; SKIP:0, research-only bounded unit utility, not financial REAL PnL");return tensor(kind,c,revision,Arrays.asList("DECLARED_SKIP","DECLARED_ACT"),Arrays.asList("COUNTERFACTUAL_K3_HIT_RATE","COUNTERFACTUAL_K3_MISS_RATE","REALIZED_RESEARCH_UNIT_UTILITY"),v,n,d);
  }return null;
 }
 static List<String> programs(List<PolicySpecR27> ps){List<String> out=new ArrayList<>();for(PolicySpecR27 p:ps)out.add(p.fullJson());return out;}
 @SuppressWarnings("unchecked") public static MatrixTensorR30R1.Tensor stored(String kind,SQLiteDatabase db,EvalContextR27 c,long revision,RuntimeR27 runtime){
  Map<String,Object> details=new LinkedHashMap<>();if(kind.equals("CAUSAL_SUPPORT")||kind.equals("COUNTER_EVIDENCE")){
   List<String> labels=new ArrayList<>();List<Map<String,Object>> rows=new ArrayList<>();try(Cursor q=db.rawQuery("SELECT m.parent_hash,m.measure_key,m.payload_json,r.run_id FROM r30r1_research_measure m JOIN r30r1_analysis_run r ON r.run_id=m.run_id WHERE m.kind='ATOM_PAIRED_GAIN' AND r.role='SELECT' AND r.status='COMMITTED' AND r.dataset_hash=? AND r.source_revision=? AND r.source_commit=? ORDER BY r.recorded_at DESC LIMIT 8",new String[]{c.data.datasetHash,String.valueOf(revision),com.ethk3.novaonepro.BuildConfig.SOURCE_COMMIT_R26})){while(q.moveToNext()){Map<String,Object> p=(Map<String,Object>)JsonR27.parse(q.getString(2));if(!(p.get("blocks") instanceof List))continue;if(kind.equals("COUNTER_EVIDENCE")&&(!(p.get("upper95") instanceof Number)||((Number)p.get("upper95")).doubleValue()>=0))continue;labels.add(q.getString(0)+":"+q.getString(1));p.put("sourceRun",q.getString(3));p.remove("checkpoint");rows.add(p);}}if(rows.isEmpty())return null;
   if(kind.equals("CAUSAL_SUPPORT")){double[][] v=new double[rows.size()][3];long[][] n=new long[rows.size()][3];for(int i=0;i<rows.size();i++){Map<String,Object> p=rows.get(i);Map<?,?> contract=(Map<?,?>)p.get("sourceContract");PolicySpecR27 parent=PolicySpecR27.parse((String)p.get("parent"));boolean exact=DirectedResearchPolicyR30R1.withoutChild(parent,(String)p.get("componentPath"),0).policyHash().equals(p.get("counterfactualHash"));v[i][0]=contract!=null&&"SELECT".equals(contract.get("role"))?1:0;v[i][1]=exact?1:0;v[i][2]=((Number)p.get("completeBlocks")).doubleValue();n[i][0]=n[i][1]=1;n[i][2]=((Number)p.get("evaluatedIssues")).longValue();}details.put("sourceReceipts",rows);details.put("meaning","Checks the actual controlled ablation assumptions; does not identify natural causality");return tensor(kind,c,revision,labels,Arrays.asList("RESEARCH_ROLE_PROVED","EXACT_MEASURED_CHILD","COMPLETE_CALENDAR_BLOCKS"),v,n,details);}
   int columns=0;for(Map<String,Object> p:rows)columns=Math.max(columns,Math.min(16,((List<?>)p.get("blocks")).size()));double[][] v=new double[rows.size()][columns];long[][] n=new long[rows.size()][columns];List<String> cols=new ArrayList<>();for(int k=0;k<columns;k++)cols.add("REGISTERED_BLOCK_SLOT:"+k);for(int i=0;i<rows.size();i++){List<?> blocks=(List<?>)rows.get(i).get("blocks");for(int k=0;k<Math.min(columns,blocks.size());k++){Map<?,?> block=(Map<?,?>)blocks.get(k);if(Boolean.TRUE.equals(block.get("included"))&&block.get("meanGain") instanceof Number){v[i][k]=((Number)block.get("meanGain")).doubleValue();n[i][k]=((Number)block.get("presentIssues")).longValue();}}}details.put("sourceReceipts",rows);details.put("scope","Negative complete-block source component evidence; per-row block boundaries remain in original receipts");return tensor(kind,c,revision,labels,cols,v,n,details);
  }
  if(kind.equals("EVOLUTION_CREDIT")){
   try(Cursor q=db.rawQuery("SELECT m.payload_json,r.run_id FROM r30r1_research_measure m JOIN r30r1_analysis_run r ON r.run_id=m.run_id WHERE m.kind='OPERATOR_GAIN_COST' AND r.role='SELECT' AND r.dataset_hash=? AND r.source_revision=? AND r.source_commit=? ORDER BY r.recorded_at DESC LIMIT 1",new String[]{c.data.datasetHash,String.valueOf(revision),com.ethk3.novaonepro.BuildConfig.SOURCE_COMMIT_R26})){if(!q.moveToFirst())return null;Map<String,Object> original=(Map<String,Object>)JsonR27.parse(q.getString(0));Map<String,Object> frame=(Map<String,Object>)original.get("frame");List<?> points=(List<?>)frame.get("points");if(points.isEmpty())return null;List<String> operators=new ArrayList<>(),children=new ArrayList<>();for(Object o:points){Map<?,?> p=(Map<?,?>)o;String op=String.valueOf(p.get("operator")),child=String.valueOf(p.get("childHash"));if(!operators.contains(op))operators.add(op);if(!children.contains(child))children.add(child);}double[][] v=new double[operators.size()][children.size()];long[][] n=new long[operators.size()][children.size()];for(Object o:points){Map<?,?> p=(Map<?,?>)o;if(p.get("value") instanceof Number){int a=operators.indexOf(String.valueOf(p.get("operator"))),b=children.indexOf(String.valueOf(p.get("childHash")));v[a][b]=((Number)p.get("value")).doubleValue();n[a][b]=((Number)p.get("n")).longValue();}}details.put("sourceRun",q.getString(1));details.put("pairedChildren",points);details.put("objectCpu","UNKNOWN_NOT_SUBSTITUTED_FROM_POOL");return tensor(kind,c,revision,operators,children,v,n,details);}
  }
  if(kind.equals("RESOURCE_EFFICIENCY")){
   if(runtime==null)return null;List<Map<String,Object>> costs=runtime.pool.researchCosts();if(costs.isEmpty())return null;if(costs.size()>64)costs=costs.subList(0,64);List<String> rows=new ArrayList<>();double[][] v=new double[costs.size()][4];long[][] n=new long[costs.size()][4];for(int i=0;i<costs.size();i++){Map<String,Object> cost=costs.get(i);rows.add(String.valueOf(cost.get("task")));v[i][0]=((Number)cost.get("actualContinuationCpuNs")).doubleValue()/1000000;v[i][1]=((Number)cost.get("quanta")).doubleValue();n[i][0]=n[i][1]=((Number)cost.get("quanta")).longValue();}details.put("actualTaskCosts",costs);details.put("missingResources","Per-task memory and queue wait are not measured; no values fabricated");details.put("unitScope","Actual current-session continuation CPU milliseconds and quanta; not per-policy CPU or an independent issue count");return tensor(kind,c,revision,rows,Arrays.asList("ACTUAL_CPU_MS","OBSERVED_QUANTA","MEMORY_BYTES_UNKNOWN","QUEUE_WAIT_MS_UNKNOWN"),v,n,details);
  }
  if(kind.equals("TEMPORAL_PRECEDENCE")){
   ResearchInputPinR30R1.requireReady(db);
   try(Cursor q=db.rawQuery("SELECT m.payload_json,m.from_ordinal,r.run_id,r.dataset_hash,r.source_revision FROM r30r1_research_measure m JOIN r30r1_analysis_run r ON r.run_id=m.run_id WHERE m.kind='MODEL_PAIR_FROZEN' AND r.role='ONLINE_RESEARCH' AND r.status='ONLINE_MODEL_ROLE_REGISTERED' AND ("+ResearchInputPinR30R1.validRunSql("r")+") ORDER BY m.from_ordinal DESC LIMIT 1",null)){if(!q.moveToFirst())return null;Map<String,Object> p=ModelReplayStudyR30R1.verified(q.getString(0));long frozen=((Number)p.get("frozenAt")).longValue(),deadline=((Number)p.get("deadlineAt")).longValue();double[][] v={{frozen-((Number)p.get("currentAvailableAt")).longValue(),deadline-frozen},{frozen-((Number)p.get("previousAvailableAt")).longValue(),deadline-frozen}};long[][] n={{1,1},{1,1}};details.put("originalReceipt",p);details.put("sourceRun",q.getString(2));long target=q.getLong(1);return new MatrixTensorR30R1.Tensor(kind,"ONLINE_RESEARCH",q.getString(3),(String)p.get("currentModelHash"),TargetIssueResolver.fromSequenceOrdinalSU1(target-1),TargetIssueResolver.fromSequenceOrdinalSU1(target),q.getLong(4),Arrays.asList("CURRENT_MODEL","PREVIOUS_MODEL"),Arrays.asList("AVAILABLE_BEFORE_FREEZE_MS","FREEZE_BEFORE_DEADLINE_MS"),v,n,details);}
  }return null;
 }
}
